using System;using System.Collections.Generic;using System.Globalization;using System.IO;using CosmicBlock.Core;using CosmicBlock.UI;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;
public static class Sprint76HomePlayProbe{
static double started;static int frames,oe,ov;static bool he,hv;static string errors="";static List<string> results=new List<string>();static GameSession session;static GameFlowController flow;static Transform safe,home;static Sprite hero;
public static void Run(){he=PlayerPrefs.HasKey(PlanetRestoration.DefaultKey);hv=PlayerPrefs.HasKey(PlanetRestoration.VersionKey);oe=PlayerPrefs.GetInt(PlanetRestoration.DefaultKey);ov=PlayerPrefs.GetInt(PlanetRestoration.VersionKey);PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,0);PlayerPrefs.SetInt(PlanetRestoration.VersionKey,PlanetRestoration.CurrentVersion);PlayerPrefs.Save();EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");started=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
static void Check(){if(EditorApplication.timeSinceStartup-started>180){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<35)return;try{session=UnityEngine.Object.FindAnyObjectByType<GameSession>();flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();safe=GameObject.Find("GameCanvas").transform.Find("SafeArea");home=safe.Find("HomeRoot");Req(flow.Screen==FlowScreen.Home,"HOME");hero=Img("HeroArea/HeroPlanet").sprite;Req(hero.name=="home_planet_hero"&&Img("HeroArea/HeroPlanet").preserveAspect,"hero");Req(home.Find("EnergyArea")==null&&home.Find("CurrentPlanetArea")==null,"energy removed");Req(Img("TitleArea/Title").sprite.name=="home_title_starlight_block","title");Req(Img("MainActions/GameStartButton").sprite.name=="home_play_button"&&Img("MainActions/PlanetCollectionButton").sprite.name=="home_collection_button","actions");Req(Img("BestScoreArea/Frame").sprite.name=="home_best_score_frame","score frame");Req(Img("BottomActions/SettingsButton/Icon").sprite.name=="home_settings_icon"&&Img("BottomActions/QuitButton/Icon").sprite.name=="home_exit_icon","utilities");Req(home.Find("BottomActions/SettingsButton/Label").GetComponent<Text>().alignment==TextAnchor.MiddleLeft&&home.Find("BottomActions/QuitButton/Label").GetComponent<Text>().alignment==TextAnchor.MiddleLeft,"utility labels right of icons");foreach(int e in new[]{0,20,50,90,115,400}){session.DebugSetPlanetEnergy(e);flow.RefreshHome();Req(Img("HeroArea/HeroPlanet").sprite==hero&&home.Find("EnergyArea")==null,"invariant "+e);}results.Add("PASS fixed hero; no HOME Energy UI.");var score=home.Find("BestScoreArea/BestScore").GetComponent<Text>();Req(score.resizeTextForBestFit&&score.alignment==TextAnchor.MiddleCenter&&score.resizeTextMaxSize>=36,"score style");foreach(int v in new[]{0,4100,99999,999999,1245600,9999999}){score.text=v.ToString("N0",CultureInfo.InvariantCulture);Canvas.ForceUpdateCanvases();Req(score.cachedTextGenerator.characterCountVisible>=score.text.Length,"score "+score.text);}flow.RefreshHome();results.Add("PASS score 0 through 9,999,999.");Capture(1080,1920,"9x16",false);Capture(1080,2400,"tall_safe",true);Capture(1080,1440,"short",false);home.Find("MainActions/GameStartButton").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Game,"PLAY");flow.RequestHome();flow.ConfirmHome();Req(flow.Screen==FlowScreen.Home&&Img("HeroArea/HeroPlanet").sprite==hero,"return");Req(errors.Length==0,"errors "+errors);results.Add("PASS responsive and flow.");Finish(true,"");}catch(Exception x){Finish(false,x.ToString());}}
static void Capture(int w,int h,string n,bool inset){var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var cam=Camera.main;var sr=safe as RectTransform;var sa=sr.GetComponent<SafeArea>();bool en=sa.enabled;var mode=canvas.renderMode;var wc=canvas.worldCamera;var target=cam.targetTexture;bool ortho=cam.orthographic;float os=cam.orthographicSize;var active=RenderTexture.active;var amin=sr.anchorMin;var amax=sr.anchorMax;var omin=sr.offsetMin;var omax=sr.offsetMax;var rt=new RenderTexture(w,h,24);Texture2D tex=null;try{sa.enabled=false;rt.Create();cam.targetTexture=rt;cam.orthographic=true;cam.orthographicSize=h/2f;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;sr.anchorMin=inset?new Vector2(.02f,.04f):Vector2.zero;sr.anchorMax=inset?new Vector2(.98f,.94f):Vector2.one;sr.offsetMin=sr.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();home.Find("HomeBackground").GetComponent<AspectFillBackground>().SendMessage("Apply");Canvas.ForceUpdateCanvases();Layout(n);cam.Render();RenderTexture.active=rt;tex=new Texture2D(w,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,w,h),0,0);tex.Apply();Directory.CreateDirectory("Validation");File.WriteAllBytes("Validation/sprint76_home_"+n+".png",tex.EncodeToPNG());}finally{canvas.renderMode=mode;canvas.worldCamera=wc;cam.targetTexture=target;cam.orthographic=ortho;cam.orthographicSize=os;RenderTexture.active=active;sr.anchorMin=amin;sr.anchorMax=amax;sr.offsetMin=omin;sr.offsetMax=omax;sa.enabled=en;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
static void Layout(string n){string[] paths={"TitleArea","HeroArea","MainActions","BestScoreArea","BottomActions"};Rect prev=new Rect();bool first=true;foreach(string p in paths){Rect r=World(home.Find(p)as RectTransform);Req(r.width>20&&r.height>20,"visible "+p+" "+n);if(!first&&p!="MainActions")Req(r.yMax<=prev.yMin+4,"overlap "+p+" "+n);prev=r;first=false;}Req(!World(home.Find("BottomActions/SettingsButton")as RectTransform).Overlaps(World(home.Find("BottomActions/QuitButton")as RectTransform)),"utility overlap");}
static Rect World(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}static Image Img(string p){return home.Find(p).GetComponent<Image>();}static void Req(bool v,string m){if(!v)throw new Exception("Sprint 7.6 failed: "+m);}static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}static void Finish(bool pass,string fail){EditorApplication.update-=Check;Application.logMessageReceived-=Log;if(he)PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,oe);else PlayerPrefs.DeleteKey(PlanetRestoration.DefaultKey);if(hv)PlayerPrefs.SetInt(PlanetRestoration.VersionKey,ov);else PlayerPrefs.DeleteKey(PlanetRestoration.VersionKey);PlayerPrefs.Save();Directory.CreateDirectory("Validation");File.WriteAllText("Validation/sprint76.txt",string.Join("\n",results)+"\n"+(pass?"SPRINT76_HOME_PASS":fail));if(pass)Debug.Log("SPRINT76_HOME_PASS");else Debug.LogError(fail);EditorApplication.Exit(pass?0:1);}}


